import Foundation

// MARK: - Module 2: Gentle reflection card deck
// Each card maps only to a present emotion, an overlooked thought, and gentle guidance. It does not represent future events or outcomes.

enum TarotDeck {
    static let all: [TarotCard] = [
        TarotCard(id: "moon-gate", name: "Moon Gate", glyph: "☾", theme: "Quiet", primaryHex: "8D86B8", secondaryHex: "D9D3F0",
                  emotionCore: "Your feelings are like the tide at night: quiet on the surface, still slowly rising and falling underneath.",
                  thoughtCore: "You may already know that you need rest. You are simply waiting for permission to stop.",
                  adviceCore: "Postpone one non-urgent task tonight and treat this blank space as a real appointment.",
                  keywords: ["Quiet", "Permission", "Night air"]),
        TarotCard(id: "still-water", name: "Heart of Still Water", glyph: "≈", theme: "Calm", primaryHex: "7FA9B7", secondaryHex: "D9EEF2",
                  emotionCore: "You are slowly settling after a busy spell. Your body feels the calm before language can name it.",
                  thoughtCore: "What you truly want may not be more answers, but a space where you are not questioned.",
                  adviceCore: "Notice the temperature of the water and the length of your breath. Let calm happen first; there is no need to explain it.",
                  keywords: ["Calm", "Space", "Flow"]),
        TarotCard(id: "cloud-stairs", name: "Stairs Above the Clouds", glyph: "⌁", theme: "Forward", primaryHex: "A79BC8", secondaryHex: "EEF2F8",
                  emotionCore: "You are hesitant about the next step, but you have not stayed in place. Your feet are already testing a new height.",
                  thoughtCore: "You are overlooking how far you have come because you are fixed on what is still ahead.",
                  adviceCore: "Lower the goal to 'one step today', then decide what comes next.",
                  keywords: ["One step", "Try", "Height"]),
        TarotCard(id: "warm-window", name: "Warm Window", glyph: "✦", theme: "Settling", primaryHex: "C8A785", secondaryHex: "F6E8D5",
