        TarotCard(id: "soft-cloud", name: "Soft Cloud", glyph: "☁", theme: "Ease", primaryHex: "A7BED2", secondaryHex: "EDF5FA",
                  emotionCore: "You are tired, yet you are still asking yourself to hold on a little longer.",
                  thoughtCore: "You need care, not another proof that you can manage everything.",
