        TarotCard(id: "white-feather", name: "White Feather", glyph: "❧", theme: "Lightness", primaryHex: "B6C5D8", secondaryHex: "F1F5FA",
                  emotionCore: "You want to set down some weight that is not yours to carry, even if only a little.",
                  thoughtCore: "Inside, you know that some responsibilities do not need to rest on you alone.",
                  adviceCore: "Choose one thing you can hand over or postpone, and say clearly, 'I am not taking this on this time.'",
                  keywords: ["Let go", "Responsibility", "Lightness"]),
        TarotCard(id: "mountain-echo", name: "Mountain Echo", glyph: "△", theme: "Response", primaryHex: "929E93", secondaryHex: "E7EBE4",
                  emotionCore: "You long for your voice to be heard, and you are also learning to hear it yourself.",
                  thoughtCore: "You overlook that you do not need to be completely ready before you are allowed to express a need.",
                  adviceCore: "Tell someone close to you in one sentence whether you need listening, company, or some quiet time.",
                  keywords: ["Need", "Echo", "Expression"]),
        TarotCard(id: "slow-clock", name: "Slow Clock", glyph: "◷", theme: "Patience", primaryHex: "B8A7A0", secondaryHex: "F1E8E4",
                  emotionCore: "You are a little impatient and want to see change now, but recovery does not obey urgency.",
                  thoughtCore: "You mistake slowness for regression and overlook that slowing down can be a conscious form of protection.",
                  adviceCore: "Change today's progress target to 'maintain'. Do not chase more; care for what is already there.",
                  keywords: ["Patience", "Maintain", "Protection"]),
        TarotCard(id: "orange-sunlight", name: "Orange Sunlight", glyph: "☀︎", theme: "Warmth", primaryHex: "D5AA79", secondaryHex: "F8EBD8",
