        TarotCard(id: "deep-whale", name: "Deep Whale Song", glyph: "≋", theme: "Depth", primaryHex: "6F8DA8", secondaryHex: "D7E7F1",
                  emotionCore: "Your feelings run deeper than the surface. Some emotions need to be heard slowly rather than handled immediately.",
                  thoughtCore: "You hope someone will understand your silence instead of urging you to feel better quickly.",
                  adviceCore: "Give yourself an uninterrupted stretch of quiet. Listen to music, write one feeling, or simply sit still.",
                  keywords: ["Depth", "Heard", "Quiet"])
    ]

    static func spread(count: Int = 9) -> [TarotCard] {
        Array(all.shuffled().prefix(min(max(count, 3), all.count)))
    }
}